INSERT INTO `movies` (`id`, `status`, `urlkey`, `title`, `content`, `published_date`, `release_date`, `thumbnail_id`, `medium_id`, `image_id`, `portrait_id`, `portraitsmall_id`, `duration`, `age_restriction`, `certificate`, `certificate_text`, `tag_text`, `is_upcoming`, `topten`, `movie_access`, `trailer_url`, `trailer_url_480p`, `video_url`, `video_url_480p`, `video_url_720p`, `video_url_1080p`, `moviesource`, `subtitle_status`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(1, 1, 'battery', 'Battery', '<p class=\"MsoNormal\">Battery is a Indian Tamil-language crime thriller directed by Mani Bharathi and starring Senguttuvan, Ammu abhirami and Deepak Shetty. Based on the subject of medical corruption.</p>', '2020-10-30 00:00:00', '2020-10-30', 105, 107, 109, 108, 106, '8640', 13, 'U/A 13+', 'tobacoo, substances, violence', 'Voilent, Action, Thriller', 1, 1, 0, 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/BatteryEncoded/Trailer/TRAILER-FOR-YOU-TUBE.mp4', 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/BatteryEncoded/Trailer/TRAILER-FOR-YOU-TUBE.mp4', 'https://d2vkl8k9v6nxyr.cloudfront.net/Battery-new-test/Battery-22.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/BatteryEncoded/BATTERY_UHD.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/Battery-new-test/Battery-22.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/BatteryEncoded/BATTERY_UHD.m3u8', 'https://bestcast-mobile-download-movies.s3.amazonaws.com/Movies/Battery-Mobile-21.mp4', 1, NULL, 2, '2024-04-13 09:53:47', '2024-05-23 04:43:43'),
(2, 1, 'grandma', 'Grandma', '<p class=\"MsoNormal\">A small girl keeps talking to the spirit of her dead grandmother. When her private tutor finds out about this, she sets out to help the girl and the spirit.</p>', '2020-10-30 00:00:00', '2022-04-14', 95, 97, 99, 98, 96, '8640', 13, 'U/A 13+', 'tobacoo, substances, violence', 'Voilent, Action, Thriller', 0, 0, 1, NULL, NULL, 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/Grandma_Encoded/GRANDMA.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/Grandma_Encoded/GRANDMA.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/Grandma_Encoded/GRANDMA.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/Grandma_Encoded/GRANDMA.m3u8', NULL, 1, NULL, 194, '2024-04-13 09:53:47', '2025-02-14 13:28:02'),
(3, 1, 'pichuvakathi', 'Pichuvakathi', '<p class=\"MsoNormal\">The lives of three friends, who get booked in a petty offense, turn topsy-turvy when they engage in illegal acts to overcome the hurdles they face.</p>', '2020-10-30 00:00:00', '2020-10-30', 100, 102, 104, 103, 101, '8640', 13, 'U/A 13+', 'tobacoo, substances, violence', 'Action, Drama', 0, 0, 0, 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/Pichuvakathi_Encoded/Pichuvakathi_trailer/Pichuva Kaththi - Official Trailer _ Inigo Prabhakaran, CM Senguttuvan _ Trend Music.mp4', 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/Pichuvakathi_Encoded/Pichuvakathi_trailer/Pichuva Kaththi - Official Trailer _ Inigo Prabhakaran, CM Senguttuvan _ Trend Music.mp4', 'https://d2vkl8k9v6nxyr.cloudfront.net/Pichuvakathi-Encoded/PICHUVAKATHI_UHD.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/Pichuvakathi-Encoded/PICHUVAKATHI_UHD.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/Pichuvakathi-Encoded/PICHUVAKATHI_UHD.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/Pichuvakathi-Encoded/PICHUVAKATHI_UHD.m3u8', 'https://bestcast-mobile-download-movies.s3.amazonaws.com/Movies/samp20.mov', 1, NULL, 2, '2024-04-13 09:53:47', '2024-10-24 09:12:15'),
(4, 1, 'ag', 'Anbulla Ghilli', '<p><span style=\"font-size: 14.0pt; line-height: 107%; font-family: \'Calibri\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: Calibri; mso-fareast-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-font-family: \'Times New Roman\'; mso-bidi-theme-font: minor-bidi; mso-ansi-language: EN-IN; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">The film traces the life of Ramu and Ghilli, the dog, are close friends. Ramu finds himself caught in a love triangle. Ghilli helps Ramu find true love. Their life is stirred up by Sundar, a ruthless poacher disguised as a forest ranger.</span></p>', '2020-10-30 00:00:00', '2022-02-06', 85, 87, 89, 88, 86, '8640', 13, 'U/A 13+', 'tobacoo, substances, violence', 'Comedy', 0, 0, 0, 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/Anbulla_Ghilli_Encoded/Trailor_Encoded/Anbulla-Ghilli.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/Anbulla_Ghilli_Encoded/Trailor_Encoded/Anbulla-Ghilli.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/Anbulla_Ghilli_Encoded/Anbulla_Ghilli.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/Anbulla_Ghilli_Encoded/Anbulla_Ghilli.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/Anbulla_Ghilli_Encoded/Anbulla_Ghilli.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/Anbulla_Ghilli_Encoded/Anbulla_Ghilli.m3u8', 'https://bestcast-mobile-download-movies.s3.amazonaws.com/Movies/AG_Mobile.mp4', 1, NULL, 2, '2024-04-13 09:53:47', '2024-05-02 06:34:35'),
(5, 1, 'maayanizhal-1713344173', 'Maayanizhal', '<p><span style=\"font-size: 11.0pt; line-height: 107%; font-family: \'Calibri\',sans-serif; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: Calibri; mso-fareast-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-font-family: \'Times New Roman\'; mso-bidi-theme-font: minor-bidi; mso-ansi-language: EN-IN; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">John Baby, a judicial magistrate who is recouping from a traumatic accident, meets Nitin, an eight-year-old boy who interests him with murder stories. When Baby explores the possibility of Nitin`s stories by mapping the events, it matches with the real-time incidents.</span></p>', '2024-04-01 00:00:00', '2021-10-28', 110, 112, 114, 113, 111, '7440', 0, 'U/A 13+', NULL, 'Thriller', 0, 0, 0, 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/Maaya_Nizhal_Encoded/Trailer/Maya-Nizhal.mp4', 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/Maaya_Nizhal_Encoded/Trailer/Maya-Nizhal.mp4', 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/Maaya_Nizhal_Encoded/MAAYA-NIZHAL.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/Maaya_Nizhal_Encoded/MAAYA-NIZHAL.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/Maaya_Nizhal_Encoded/MAAYA-NIZHAL.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/Maaya_Nizhal_Encoded/MAAYA-NIZHAL.m3u8', 'https://bestcast-mobile-download-movies.s3.amazonaws.com/Movies/trailer-720p.mp4', 0, 2, 2, '2024-04-17 03:26:13', '2024-05-23 10:49:03'),
(6, 1, 'college-kumar-1713344208', 'College Kumar', '<p class=\"MsoNormal\">After his son challenges him to study and become an auditor, a father joins his son\'s college to teach him a lesson about hard work and determination.</p>', '2024-04-17 00:00:00', '2020-03-06', 115, 117, 119, 118, 116, '7260', 0, 'U/A 13+', NULL, 'Drama', 0, 0, 0, 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/College_kumar_Encoded/College-kumar-encodedtrailer/College_Kumar_trailer.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/College_kumar_Encoded/College-kumar-encodedtrailer/College_Kumar_trailer.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/College_kumar_Encoded/College_Kumar_Tamil_Movie.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/College_kumar_Encoded/College_Kumar_Tamil_Movie.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/College_kumar_Encoded/College_Kumar_Tamil_Movie.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/College_kumar_Encoded/College_Kumar_Tamil_Movie.m3u8', NULL, 0, 2, 2, '2024-04-17 03:26:48', '2024-04-30 05:29:15'),
(8, 0, 'thottal-thodarum-1729224719', 'Thottal Thodarum', '<p class=\"MsoNormal\">Shiva and Gautam are buddies and HR professionals in the same firm. Gautam\'s insatiable thirst for wooing women, leads him to abuse a bank marketing call that Shiva receives. Madhu, a miffed friend of the woman in the receiving end, starts to taunt Shiva by making prank calls which later blossoms into real romance just over the phone without having seen each other. When they feel the time is right to meet and communicate their mutual love, Madhu gets entangled in the bad books of a deadly organized crime syndicate. Her struggle to wriggle out of this with the help of Shiva and his friends is what forms the rest of the story.</p>', '2024-10-18 00:00:00', '2015-01-23', 123, 124, 120, 121, 122, '8520', 0, 'U/A 13+', NULL, 'Romance, Thriller', 0, 0, 1, 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/Thottal Thodarum/Trailer_Enc/TamilMovieThottalThodarumTrailer.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/Movies/Thottal Thodarum/Trailer_Enc/TamilMovieThottalThodarumTrailer.m3u8', 'https://vz-81060042-a1b.b-cdn.net/bcdn_token=BR_cOvYwoGOzVQAFTCxBcjw9lgyaHds6ugca0KIA7O4&expires=1729306700&token_path=%2F59c24256-484b-40a9-a677-f08c95308e81%2F/59c24256-484b-40a9-a677-f08c95308e81/playlist.m3u8', 'https://vz-81060042-a1b.b-cdn.net/bcdn_token=BR_cOvYwoGOzVQAFTCxBcjw9lgyaHds6ugca0KIA7O4&expires=1729306700&token_path=%2F59c24256-484b-40a9-a677-f08c95308e81%2F/59c24256-484b-40a9-a677-f08c95308e81/playlist.m3u8', 'https://vz-81060042-a1b.b-cdn.net/bcdn_token=BR_cOvYwoGOzVQAFTCxBcjw9lgyaHds6ugca0KIA7O4&expires=1729306700&token_path=%2F59c24256-484b-40a9-a677-f08c95308e81%2F/59c24256-484b-40a9-a677-f08c95308e81/playlist.m3u8', 'https://vz-81060042-a1b.b-cdn.net/bcdn_token=BR_cOvYwoGOzVQAFTCxBcjw9lgyaHds6ugca0KIA7O4&expires=1729306700&token_path=%2F59c24256-484b-40a9-a677-f08c95308e81%2F/59c24256-484b-40a9-a677-f08c95308e81/playlist.m3u8', NULL, 0, 2, 2, '2024-10-18 04:11:59', '2024-10-22 05:17:48'),
(13, 1, 'saroja-yarra-ivununga', 'Saroja Yarra Ivununga', '<blockquote>\r\n<p>Not just another Love story...... It\'s your Love story exposed!</p>\r\n</blockquote>', '2025-02-10 00:00:00', '2025-02-14', 129, 130, 127, 125, 126, '948', 0, 'U/A 13+', NULL, 'Romantic Comedy, Short Film', 0, 0, 1, 'https://d2vkl8k9v6nxyr.cloudfront.net/saroja-Yarra-Ivununga/saroja-yarra-ivununga-trailer.mp4', 'https://d2vkl8k9v6nxyr.cloudfront.net/saroja-Yarra-Ivununga/saroja-yarra-ivununga-trailer.mp4', 'https://d2vkl8k9v6nxyr.cloudfront.net/saroja-Yarra-Ivununga/encoded-file/saroja_yaarra_ivununga.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/saroja-Yarra-Ivununga/encoded-file/saroja_yaarra_ivununga.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/saroja-Yarra-Ivununga/encoded-file/saroja_yaarra_ivununga.m3u8', 'https://d2vkl8k9v6nxyr.cloudfront.net/saroja-Yarra-Ivununga/encoded-file/saroja_yaarra_ivununga.m3u8', NULL, 1, 194, 194, '2025-02-14 12:13:06', '2025-02-15 12:09:25');
