INSERT INTO `post_content` (`id`, `user_id`, `post_id`, `content`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(1, 0, 1, '<p>Watch anywhere. Cancel anytime.</p>', NULL, 2, '2024-04-13 09:53:47', '2024-04-16 00:29:46'),
(2, 0, 6, '<p style=\"text-align: center;\" data-start=\"63\" data-end=\"123\">&nbsp;</p>\r\n<p style=\"text-align: center;\" data-start=\"63\" data-end=\"123\"><strong data-start=\"63\" data-end=\"123\">Join BestCast OTT &ndash; Where Innovation Meets Entertainment</strong></p>\r\n<p style=\"text-align: center;\" data-start=\"125\" data-end=\"604\">At <strong>BestCast OTT</strong>, we&rsquo;re redefining the streaming experience with cutting-edge technology and diverse content. We&rsquo;re looking for passionate, creative, and driven individuals to help us shape the future of digital entertainment. Whether you\'re a tech enthusiast, a content creator, or a customer-focused professional, there&rsquo;s a place for you to grow and make an impact. Explore career opportunities with us and be part of a dynamic team that&rsquo;s changing the way the world watches TV.</p>', NULL, 194, '2024-04-13 09:53:47', '2025-02-17 10:07:08');
